-- k8s 세트 351. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set351.sql. 단원·display_order·아이콘은 통합 시 별도로 정한다. docs/specs/spec_k8s_resources_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 351, '리소스 requests·limits 손연습: set resources, QoS 등급, LimitRange 기본값, ResourceQuota 사용량과 초과', 'kubectl set resources 와 YAML 로 requests·limits 를 정하고 jsonpath 로 읽습니다. .status.qosClass 로 Guaranteed·Burstable 등급을 확인하고 requests 와 limits 를 같게 맞춰 Guaranteed 로 바꿉니다. 리소스를 안 쓴 Pod 에 LimitRange 기본값이 채워지는 것, 컨테이너 상한(max)을 넘어 Pod 가 안 생기는 것, ResourceQuota 의 Used 와 Hard 읽기, 쿼터 초과로 일부 복제본만 뜨는 Deployment 고치기를 해 봅니다. 채점은 Deployment 템플릿·Pod 의 resources 와 qosClass, 쿼터 상태, 저장한 파일의 내용을 확인합니다.', 'k8s', 'k8s'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 351);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 1, 'kubectl set resources 로 requests 와 limits 정하기', 'Deployment `rs351-web`(복제본 1개, 이미지 `nginx:1.25`)에는 아직 자원을 정해 두지 않았습니다. **`kubectl set resources`** 로 컨테이너에 requests 는 `cpu=100m`, `memory=64Mi`, limits 는 `cpu=200m`, `memory=128Mi` 를 정하세요. 새 설정으로 Pod 가 교체되어 Running 이어야 합니다.', '`kubectl set resources --help` 에 requests 와 limits 를 각각 정하는 옵션이 있어요. 값은 `cpu=...,memory=...` 처럼 쉼표로 이어 줄 수 있습니다.', 'kubectl set resources deployment rs351-web --requests=cpu=100m,memory=64Mi --limits=cpu=200m,memory=128Mi -n $NS
kubectl rollout status deployment/rs351-web -n $NS
kubectl get deployment rs351-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources}''

# Pod 템플릿이 바뀌므로 Pod 가 새로 만들어진다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: rs351-web\\n  labels:\\n    etude: lab351\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: rs351-web\\n  template:\\n    metadata:\\n      labels:\\n        app: rs351-web\\n        etude: lab351\\n    spec:\\n      containers:\\n      - name: c\\n        image: nginx:1.25\\n---\\nEOF\\nkubectl rollout status deployment/rs351-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment rs351-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}-{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"100m-64Mi\\" ] ) && ( [ \\"$(kubectl get deployment rs351-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.cpu}-{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"200m-128Mi\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-web -o jsonpath=''{range .items[*]}{.status.phase}-{.spec.containers[0].resources.limits.memory}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running-128Mi\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Deployment 템플릿의 requests 가 cpu 100m, memory 64Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}-{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"100m-64Mi\\" ]"]}, {"label": "limits 가 cpu 200m, memory 128Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.cpu}-{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"200m-128Mi\\" ]"]}, {"label": "새 설정의 Pod 하나만 남아 Running 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-web -o jsonpath=''{range .items[*]}{.status.phase}-{.spec.containers[0].resources.limits.memory}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running-128Mi\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 2, 'jsonpath 로 메모리 limits 값만 읽어 저장하기', 'Pod `rs351-reader` 에는 requests 와 limits 가 정해져 있습니다. **memory 의 limits 값만** 출력하는 `-o jsonpath` 를 만들어, 그 값을 파일 **`/tmp/memlimit.txt`** 에 저장하세요. (requests 값과 헷갈리지 마세요.)', '`kubectl get pod 이름 -o yaml` 로 `resources` 의 모양을 먼저 보고, 그 경로를 `-o jsonpath=''{.spec.containers[0]...}''` 로 따라가 보세요. 저장은 `>` 로 해요.', 'kubectl get pod rs351-reader -n $NS -o yaml | grep -A8 resources
kubectl get pod rs351-reader -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' > /tmp/memlimit.txt
cat /tmp/memlimit.txt

# requests 값은 .resources.requests.memory 로 따로 있다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: rs351-reader\\n  labels:\\n    etude: lab351\\nspec:\\n  containers:\\n  - name: c\\n    image: nginx:1.25\\n    resources:\\n      requests:\\n        cpu: 150m\\n        memory: 96Mi\\n      limits:\\n        cpu: 300m\\n        memory: 192Mi\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab351 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -n \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/memlimit.txt 2>/dev/null)\\" = \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ] ) && ( [ \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.status.phase}-{.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"Running-96Mi\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일 내용이 Pod 의 memory limits 값과 같다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/memlimit.txt 2>/dev/null)\\" = \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ]"]}, {"label": "Pod rs351-reader 는 그대로 Running 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod rs351-reader -n $NS -o jsonpath=''{.status.phase}-{.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"Running-96Mi\\" ]"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 3, 'YAML 로 requests 와 limits 가 있는 Pod 만들기', 'YAML 로 Pod **`rs351-yaml`**(이미지 `nginx:1.25`)을 만드세요. 컨테이너에 requests 는 `cpu: 50m`, `memory: 32Mi`, limits 는 `cpu: 100m`, `memory: 64Mi` 를 적고, Pod 가 Running 이 되어야 합니다.', '`kubectl run 이름 --image=... --dry-run=client -o yaml` 로 뼈대를 얻은 뒤, 컨테이너 항목 안에 `resources:` 를 더하면 돼요. `resources` 아래에 `requests` 와 `limits` 가 나란히 들어갑니다.', 'kubectl apply -n $NS -f - <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: rs351-yaml
spec:
  containers:
  - name: c
    image: nginx:1.25
    resources:
      requests:
        cpu: 50m
        memory: 32Mi
      limits:
        cpu: 100m
        memory: 64Mi
EOF
kubectl get pod rs351-yaml -n $NS', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.spec.containers[0].resources.requests.cpu}-{.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"50m-32Mi\\" ] ) && ( [ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.cpu}-{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"100m-64Mi\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "requests 가 cpu 50m, memory 32Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.spec.containers[0].resources.requests.cpu}-{.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"50m-32Mi\\" ]"]}, {"label": "limits 가 cpu 100m, memory 64Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.cpu}-{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"100m-64Mi\\" ]"]}, {"label": "Pod 가 Running 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod rs351-yaml -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 4, 'Pod 의 QoS 등급 읽어 저장하기', 'Pod `rs351-qos` 에는 requests 와 limits 가 정해져 있습니다. 쿠버네티스가 이 Pod 에 붙인 **QoS 등급**(`.status` 아래에 있어요)을 jsonpath 로 읽어 **`/tmp/qos.txt`** 에 저장하세요.', '`kubectl get pod 이름 -o yaml` 맨 아래 `status:` 쪽을 보면 등급을 나타내는 키가 있어요. 그 경로를 `-o jsonpath` 로 적고 `>` 로 저장합니다.', 'kubectl get pod rs351-qos -n $NS -o yaml | tail -8
kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.qosClass}'' > /tmp/qos.txt
cat /tmp/qos.txt

# requests 와 limits 가 있지만 서로 다르면 Burstable', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: rs351-qos\\n  labels:\\n    etude: lab351\\nspec:\\n  containers:\\n  - name: c\\n    image: nginx:1.25\\n    resources:\\n      requests:\\n        cpu: 100m\\n        memory: 64Mi\\n      limits:\\n        cpu: 200m\\n        memory: 128Mi\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab351 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -n \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.qosClass}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/qos.txt 2>/dev/null)\\" = \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.qosClass}'' 2>/dev/null)\\" ] ) && ( [ \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.phase}-{.spec.containers[0].resources.limits.cpu}'' 2>/dev/null)\\" = \\"Running-200m\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일 내용이 Pod 의 qosClass 와 같다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.qosClass}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/qos.txt 2>/dev/null)\\" = \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.qosClass}'' 2>/dev/null)\\" ]"]}, {"label": "Pod rs351-qos 는 그대로 Running 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod rs351-qos -n $NS -o jsonpath=''{.status.phase}-{.spec.containers[0].resources.limits.cpu}'' 2>/dev/null)\\" = \\"Running-200m\\" ]"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 5, 'QoS 등급 칸을 한 번에 보기', 'Pod `rs351-qos` 의 QoS 등급을 표로 바로 보려고 합니다. 빈칸에 알맞은 필드 이름을 고르세요.', '`kubectl get pod 이름 -o yaml` 의 `status` 아래 키 이름을 떠올려 보세요. 대소문자도 정확히 써야 합니다.', NULL, NULL, '[]', 'fill', '["qosClass", "qosLevel", "QoSClass", "serviceClass"]', NULL, '등급은 Pod 의 `.status.qosClass` 에 `Guaranteed`, `Burstable`, `BestEffort` 중 하나로 들어 있습니다. `qosLevel`, `serviceClass` 는 없는 키이고, `QoSClass` 는 대문자 때문에 다른 키로 읽혀 값이 비어요. jsonpath 와 custom-columns 모두 키의 대소문자를 구분합니다.', '[0]', 'kubectl get pod rs351-qos -o custom-columns=QOS:.status.{0}', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 6, 'requests 와 limits 를 같게 해서 Guaranteed 로 만들기', 'Deployment `rs351-gu`(복제본 1개)의 Pod 는 requests 와 limits 가 서로 달라 `Burstable` 입니다. Deployment 를 지우지 말고 자원 설정을 바꿔서, 교체된 Pod 의 QoS 등급이 **`Guaranteed`** 가 되게 하세요. 값은 정해진 것이 없고, cpu 와 memory 둘 다 requests 와 limits 가 같으면 됩니다.', 'Guaranteed 는 컨테이너마다 cpu, memory 의 requests 와 limits 가 모두 있고 서로 같을 때예요. `kubectl set resources` 로 바꾸고, 새 Pod 의 `.status.qosClass` 로 확인해 보세요.', 'kubectl set resources deployment rs351-gu --requests=cpu=200m,memory=128Mi --limits=cpu=200m,memory=128Mi -n $NS
kubectl rollout status deployment/rs351-gu -n $NS
kubectl get pods -l app=rs351-gu -n $NS -o jsonpath=''{.items[*].status.qosClass}''

# limits 만 정해도 requests 가 같은 값으로 채워져 Guaranteed 가 된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: rs351-gu\\n  labels:\\n    etude: lab351\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: rs351-gu\\n  template:\\n    metadata:\\n      labels:\\n        app: rs351-gu\\n        etude: lab351\\n    spec:\\n      containers:\\n      - name: c\\n        image: nginx:1.25\\n        resources:\\n          requests:\\n            cpu: 100m\\n            memory: 64Mi\\n          limits:\\n            cpu: 200m\\n            memory: 128Mi\\n---\\nEOF\\nkubectl rollout status deployment/rs351-gu -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment rs351-gu -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"1\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-gu -o jsonpath=''{range .items[*]}{.status.phase}-{.status.qosClass}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running-Guaranteed\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Deployment 가 그대로 있고 복제본이 1개이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-gu -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"1\\" ]"]}, {"label": "남은 Pod 하나가 Running 이고 QoS 등급이 Guaranteed 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-gu -o jsonpath=''{range .items[*]}{.status.phase}-{.status.qosClass}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running-Guaranteed\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 7, '리소스를 안 쓴 Pod 에 채워진 기본값 읽기', '`kubectl run` 으로 Pod **`rs351-plain`**(이미지 `nginx:1.25`)을 **자원 옵션 없이** 만드세요. 그런데 이 네임스페이스에는 `LimitRange` 가 있어서 만든 Pod 에 값이 저절로 채워집니다. Pod 가 Running 이 되면, 채워진 **memory limits 값**을 읽어 **`/tmp/default.txt`** 에 저장하세요.', '`kubectl get limitrange -o yaml` 에 `default` 와 `defaultRequest` 가 있어요. 만든 Pod 는 `-o yaml` 의 `resources` 로 확인하고, 값 하나는 `-o jsonpath` 로 뽑아 `>` 로 저장합니다.', 'kubectl run rs351-plain --image=nginx:1.25 -n $NS
kubectl wait --for=jsonpath=''{.status.phase}''=Running pod/rs351-plain -n $NS --timeout=60s
kubectl get pod rs351-plain -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' > /tmp/default.txt
cat /tmp/default.txt
kubectl get limitrange -n $NS -o yaml | grep -A4 ''default:''

# Pod 에 쓰지 않은 requests/limits 는 LimitRange 의 defaultRequest/default 로 채워진다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod rs351-plain -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ -n \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get pod rs351-plain -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] ) && ( [ -n \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/default.txt 2>/dev/null)\\" = \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod rs351-plain 이 Running 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod rs351-plain -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "Pod 의 memory limits 가 LimitRange 의 default memory 와 같다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get pod rs351-plain -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ]"]}, {"label": "파일 내용이 그 값과 같다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/default.txt 2>/dev/null)\\" = \\"$(kubectl get limitrange -n $NS -o jsonpath=''{.items[0].spec.limits[0].default.memory}'' 2>/dev/null)\\" ]"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 8, 'YAML 에 리소스를 안 썼는데 LimitRange 기본값이 있으면', '네임스페이스에 `default` 와 `defaultRequest` 가 정해진 `LimitRange` 가 있습니다. `resources` 를 하나도 쓰지 않은 Pod YAML 을 apply 하면 어떻게 될까요?', '`LimitRange` 의 기본값은 Pod 가 만들어질 때 API 서버가 적용해요. 만들어진 Pod 를 `-o yaml` 로 읽으면 무엇이 보일까요?', NULL, NULL, '[]', 'choice', '["Pod 에는 아무것도 채워지지 않아 requests 와 limits 가 빈 채로 만들어진다", "Pod 가 만들어지지 않고 resources 를 쓰라는 오류와 함께 거부된다", "Pod 는 만들어지고 노드 사정에 맞춰 스케줄러가 값을 나중에 정해 준다", "Pod 가 만들어질 때 defaultRequest 는 requests 로, default 는 limits 로 채워진다"]', 3, '`LimitRange` 의 `defaultRequest` 는 requests 가 없는 컨테이너에, `default` 는 limits 가 없는 컨테이너에 Pod 가 만들어지는 시점에 채워 넣습니다. 그래서 만들어진 Pod 를 읽으면 값이 들어 있고, 보통 requests 와 limits 가 달라 `Burstable` 이 돼요. 값이 비어 `BestEffort` 가 되는 것은 기본값이 없는 네임스페이스에서의 모습입니다. 기본값이 있으면 거부되지 않고, 스케줄러가 나중에 값을 정해 주는 일도 없어요.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 9, 'ResourceQuota 의 Used 와 Hard 읽어 저장하기', '네임스페이스의 `ResourceQuota` 는 만들 수 있는 Pod 개수의 한도를 정해 둡니다. 지금 **사용 중인 Pod 개수(Used)** 와 **한도(Hard)** 를 읽어 **`사용/한도`** 모양(예: `3/12`)으로 **`/tmp/pods.txt`** 에 저장하세요. (Pod 두 개가 떠 있는 상태에서 시작합니다.)', '`kubectl describe quota` 에 Resource, Used, Hard 표가 나와요. 값 하나는 `kubectl get resourcequota -o jsonpath` 로 `.status.used` 와 `.status.hard` 아래에서 읽을 수 있어요.', 'kubectl describe quota -n $NS
USED=$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.used.pods}'')
HARD=$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.hard.pods}'')
echo "$USED/$HARD" > /tmp/pods.txt
cat /tmp/pods.txt

# Used 는 쿼터가 세고 있는 현재 사용량, Hard 는 넘을 수 없는 한도', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: rs351-u1\\n  labels:\\n    etude: lab351\\nspec:\\n  containers:\\n  - name: c\\n    image: nginx:1.25\\n    resources:\\n      requests:\\n        cpu: 50m\\n        memory: 32Mi\\n      limits:\\n        cpu: 100m\\n        memory: 64Mi\\n---\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: rs351-u2\\n  labels:\\n    etude: lab351\\nspec:\\n  containers:\\n  - name: c\\n    image: nginx:1.25\\n    resources:\\n      requests:\\n        cpu: 50m\\n        memory: 32Mi\\n      limits:\\n        cpu: 100m\\n        memory: 64Mi\\n---\\nEOF\\nkubectl wait --for=jsonpath=''{.status.phase}''=Running pod -l etude=lab351 -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( ( i=0; while [ $i -lt 20 ]; do if [ -n \\"$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.hard.pods}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/pods.txt 2>/dev/null)\\" = \\"$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.used.pods}/{.items[0].status.hard.pods}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get pods rs351-u1 rs351-u2 -n $NS -o jsonpath=''{.items[*].status.phase}'' 2>/dev/null)\\" = \\"Running Running\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 사용/한도 모양으로 쿼터의 현재 값과 같다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 20 ]; do if [ -n \\"$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.hard.pods}'' 2>/dev/null)\\" ] && [ \\"$(tr -d ''[:space:]'' < /tmp/pods.txt 2>/dev/null)\\" = \\"$(kubectl get resourcequota -n $NS -o jsonpath=''{.items[0].status.used.pods}/{.items[0].status.hard.pods}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "Pod rs351-u1, rs351-u2 는 그대로 Running 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pods rs351-u1 rs351-u2 -n $NS -o jsonpath=''{.items[*].status.phase}'' 2>/dev/null)\\" = \\"Running Running\\" ]"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 10, '컨테이너 상한을 넘어 Pod 가 안 생기는 Deployment 고치기', 'Deployment `rs351-over`(복제본 1개)의 Pod 가 하나도 만들어지지 않습니다. 원인은 이벤트에 적혀 있어요. **원인을 읽고**, `kubectl set resources` 로 limits 를 상한 안으로 고쳐 Pod 가 Running 이 되게 하세요. (requests 는 그대로 남겨 두세요.)', '`kubectl get events` 나 `kubectl describe replicaset` 의 Events 에서 `FailedCreate` 를 찾아 보세요. 문장에 maximum 과 함께 허용 값이 나오고, `kubectl get limitrange -o yaml` 의 `max` 와 맞춰 볼 수 있어요.', 'kubectl get deployment rs351-over -n $NS      # READY 0/1
kubectl describe replicaset -l app=rs351-over -n $NS | grep -A3 Events
kubectl get limitrange -n $NS -o yaml | grep -A3 ''max:''
kubectl set resources deployment rs351-over --limits=cpu=500m,memory=64Mi -n $NS
kubectl rollout status deployment/rs351-over -n $NS

# LimitRange 의 max 를 넘으면 Deployment 는 만들어져도 Pod 가 거부된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: rs351-over\\n  labels:\\n    etude: lab351\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: rs351-over\\n  template:\\n    metadata:\\n      labels:\\n        app: rs351-over\\n        etude: lab351\\n    spec:\\n      containers:\\n      - name: c\\n        image: nginx:1.25\\n        resources:\\n          requests:\\n            cpu: 100m\\n            memory: 32Mi\\n          limits:\\n            cpu: \\"2\\"\\n            memory: 64Mi\\n---\\nEOF\\nsleep 3; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment rs351-over -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}'' 2>/dev/null)\\" = \\"100m\\" ] ) && ( [ \\"$(kubectl get deployment rs351-over -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.cpu}'' 2>/dev/null)\\" != \\"2\\" ] ) && ( ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-over -o jsonpath=''{range .items[*]}{.status.phase}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Deployment 템플릿의 requests.cpu 는 그대로 100m 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-over -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}'' 2>/dev/null)\\" = \\"100m\\" ]"]}, {"label": "limits.cpu 가 더 이상 2 가 아니다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-over -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.cpu}'' 2>/dev/null)\\" != \\"2\\" ]"]}, {"label": "Pod 하나가 Running 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pods -n $NS -l app=rs351-over -o jsonpath=''{range .items[*]}{.status.phase}{\\"\\\\n\\"}{end}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 11, '쿼터 때문에 일부만 뜨는 Deployment 고치기', 'Deployment `rs351-fat`(복제본 3개)은 Pod 마다 memory requests 가 `700Mi` 인데, 3개 중 일부만 만들어지고 나머지는 계속 안 뜹니다. **이벤트의 원인을 읽고**, 복제본은 3개 그대로 두고 자원 값을 줄여서 **3개 모두 Running** 이 되게 하세요. (requests 와 limits 는 둘 다 남겨 두세요.)', '`kubectl describe replicaset -l app=rs351-fat` 의 Events 에 `exceeded quota` 문장이 있어요. `kubectl describe quota` 의 Used 와 Hard 를 비교해 몇 Mi 까지 줄이면 3개가 들어갈지 계산해 보세요.', 'kubectl get deployment rs351-fat -n $NS        # READY 2/3
kubectl describe replicaset -l app=rs351-fat -n $NS | grep -i quota
kubectl describe quota -n $NS
kubectl set resources deployment rs351-fat --requests=cpu=50m,memory=200Mi --limits=cpu=100m,memory=256Mi -n $NS
kubectl rollout status deployment/rs351-fat -n $NS

# 쿼터는 Pod 를 하나씩 만들 때 합계가 Hard 를 넘는지 본다. 넘으면 그 Pod 만 거부된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment,pod -l etude=lab351 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod rs351-plain rs351-yaml -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: rs351-fat\\n  labels:\\n    etude: lab351\\nspec:\\n  replicas: 3\\n  selector:\\n    matchLabels:\\n      app: rs351-fat\\n  template:\\n    metadata:\\n      labels:\\n        app: rs351-fat\\n        etude: lab351\\n    spec:\\n      containers:\\n      - name: c\\n        image: nginx:1.25\\n        resources:\\n          requests:\\n            cpu: 50m\\n            memory: 700Mi\\n          limits:\\n            cpu: 100m\\n            memory: 700Mi\\n---\\nEOF\\nsleep 5; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"3\\" ] ) && ( [ -n \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ] && [ -n \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" != \\"700Mi\\" ] ) && ( ( i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "복제본은 3개 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"3\\" ]"]}, {"label": "requests.memory 와 limits.memory 가 둘 다 남아 있고 700Mi 보다 작다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" ] && [ -n \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" ] && [ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" != \\"700Mi\\" ]"]}, {"label": "새 설정의 Pod 3개가 모두 Running 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get deployment rs351-fat -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "컨테이너 리소스 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}, {"title": "파드의 서비스 품질(QoS) 설정", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/quality-service-pod/"}, {"title": "리밋 레인지(LimitRange)", "url": "https://kubernetes.io/docs/concepts/policy/limit-range/"}, {"title": "리소스 쿼터", "url": "https://kubernetes.io/docs/concepts/policy/resource-quotas/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 351, 12, 'QoS 를 Guaranteed 로 바꾸는 순서', 'Burstable 인 Deployment 의 Pod 를 Guaranteed 로 바꾸고 확인하는 순서대로 놓아 보세요.', '먼저 지금 등급을 확인하고, 설정을 고치면 Pod 가 교체되니 기다린 뒤, 교체된 Pod 에서 다시 확인합니다.', NULL, NULL, '[]', 'order', '["`kubectl rollout status` 로 Pod 가 새로 교체될 때까지 기다린다", "교체된 새 Pod 의 `.status.qosClass` 가 Guaranteed 로 바뀌었는지 읽는다", "지금 Pod 의 `.status.qosClass` 를 읽어 Burstable 인지 확인한다", "`kubectl set resources` 로 requests 와 limits 를 같은 값으로 맞춘다"]', NULL, '먼저 지금 Pod 의 `.status.qosClass` 로 현재 등급이 Burstable 인 것을 확인합니다. 그다음 `kubectl set resources` 로 requests 와 limits 를 같게 맞추면 Pod 템플릿이 바뀌어 새 Pod 로 교체되고, `rollout status` 로 교체가 끝나길 기다려요. 마지막으로 새 Pod 의 등급을 읽어야 Guaranteed 가 됐는지 알 수 있습니다. 등급은 Pod 가 만들어질 때 정해지므로, 설정을 바꾼 뒤 기다리지 않고 읽으면 옛 Pod 의 값이 나올 수 있어요.', '[2, 3, 0, 1]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 351 AND order_index = 12);

